import {Button} from '@primer/react'
import {InlineMessage} from '@primer/react/experimental'

import {Resources} from '../constants/strings'
import styles from './IssueFieldActions.module.css'
import {IssueFieldsDelete} from './IssueFieldsDelete'

type IssueFieldActionsProps = {
  disabled?: boolean
  confirmLabel: string
  cancelLabel?: string
  onConfirm: () => void
  onCancel: () => void
  initialData: {
    name: string
    id: string
    organization: string
  }
  successMessage?: boolean
  isCreateNew?: boolean
}

export function IssueFieldActions(props: IssueFieldActionsProps) {
  const {
    disabled = false,
    onCancel,
    onConfirm,
    cancelLabel = Resources.cancelButton,
    confirmLabel,
    initialData,
    successMessage,
    isCreateNew,
  } = props

  return (
    <div className={styles.container}>
      <div className={styles.saveCancelContainer}>
        <Button variant="primary" onClick={onConfirm} data-testid="issue-type-confirm-button" disabled={disabled}>
          {confirmLabel}
        </Button>
        <Button onClick={onCancel} data-testid="issue-type-cancel-button" disabled={disabled}>
          {cancelLabel}
        </Button>
        <div className={styles.confirmationContainer}>
          {successMessage && (
            <InlineMessage className={styles.inlineMessage} variant="success">
              {Resources.saveComplete}
            </InlineMessage>
          )}
        </div>
      </div>
      {!isCreateNew && (
        <IssueFieldsDelete
          issueFieldName={initialData.name}
          issueFieldId={initialData.id}
          organization={initialData.organization}
        />
      )}
    </div>
  )
}

try{ IssueFieldActions.displayName ||= 'IssueFieldActions' } catch {}