import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useLocation} from '@github-ui/react-router'

import {IssueFieldCreateButton} from '../components/IssueFieldCreateButton'
import {IssueFieldsLimitReachedBanner} from '../components/IssueFieldsLimitReachedBanner'
import {IssueFieldsList} from '../components/IssueFieldsList'
import {Title} from '../components/Title'
import {Resources} from '../constants/strings'
import {issueFieldsSettingsIndexRoute} from './index-route'
import styles from './IndexPage.module.css'

export function IndexPage() {
  const payload = useRouteQuery(issueFieldsSettingsIndexRoute, 'mainQuery')
  const location = useLocation()
  const fieldsCount = payload.data.fields.length

  return (
    <>
      <IssueFieldsLimitReachedBanner shouldShow={!!location.state?.showLimitBanner} fieldsCount={fieldsCount} />
      <form aria-labelledby="issue-types-heading" onSubmit={e => e.preventDefault()}>
        <div className={styles.titleContainer}>
          <Title showBorder={false}>{Resources.settingsPageHeader}</Title>
          <IssueFieldCreateButton fieldsCount={fieldsCount} organizationLogin={payload.data.organization.login} />
        </div>
      </form>
      <div className={styles.infoArea}>
        <p className={styles.infoBlockTextOrg}>{Resources.infoBlockTextOrg}</p>
      </div>

      <IssueFieldsList fields={payload.data.fields} organization={payload.data.organization} />
    </>
  )
}

try{ IndexPage.displayName ||= 'IndexPage' } catch {}