import {KnownTypes} from '@github-ui/issue-fields-shared/issue-field'
import {useIssueFieldsAnalytics} from '@github-ui/issue-fields-shared/use-issue-fields-analytics'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useNavigate} from '@github-ui/use-navigate'
import {Flash} from '@primer/react'
import {useCallback, useEffect, useState} from 'react'

import {IssueFieldForm, type IssueFieldFormData} from '../components/IssueFieldForm'
import {ORGANIZATION_ISSUE_FIELDS_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import {useCreateIssueFieldMutation} from '../mutations/create-issue-field'
import {issueFieldsSettingsNewRoute} from './new-route'

export function NewPage() {
  const payload = useRouteQuery(issueFieldsSettingsNewRoute, 'mainQuery')
  const [apiError, setApiError] = useState<string | null>(null)
  const navigate = useNavigate()
  const orgLogin = payload.data.organization.login
  const orgId = payload.data.organization.id
  const createMutation = useCreateIssueFieldMutation(orgLogin)
  const fieldsCount = payload.data.fields.length
  const isLimitReached = fieldsCount >= ORGANIZATION_ISSUE_FIELDS_LIMIT
  const {markInteractionStart, reportUsage} = useIssueFieldsAnalytics()

  // Block access if field limit is reached
  useEffect(() => {
    if (isLimitReached) {
      navigate(`/organizations/${orgLogin}/settings/issue-fields`, {
        replace: true,
        state: {showLimitBanner: true},
      })
    }
  }, [isLimitReached, navigate, orgLogin])

  useEffect(() => {
    markInteractionStart()
  }, [markInteractionStart])

  const handleSubmit = useCallback(
    async (formData: IssueFieldFormData) => {
      setApiError(null)
      const startTime = Date.now()

      try {
        // Prepare options data if it's a single select field
        const options =
          formData.type === KnownTypes.single_select && formData.options
            ? formData.options.map((option, index) => ({
                name: option.name,
                color: option.color,
                description: option.description || '',
                priority: index,
              }))
            : undefined

        // Create the field (with options if applicable) in one call
        const result = await createMutation.mutateAsync({
          name: formData.name,
          data_type: formData.type.type,
          description: formData.description,
          priority: undefined,
          options,
        })

        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'create',
          fieldType: formData.type.type,
          status: 'success',
          fieldId: result.id || '',
          singleSelectOptionsCount: formData.type === KnownTypes.single_select ? formData.options?.length : undefined,
          duration,
          orgId,
        })

        // On success, redirect to the index page
        navigate(`/organizations/${orgLogin}/settings/issue-fields`)
      } catch (error) {
        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'create',
          fieldType: formData.type.type,
          status: 'error',
          fieldId: '',
          singleSelectOptionsCount: formData.type === KnownTypes.single_select ? formData.options?.length : undefined,
          errorDetails: error instanceof Error ? error.message : 'Failed to create issue field',
          duration,
          orgId,
        })

        // Field creation failed, show error on current page
        setApiError(error instanceof Error ? error.message : 'Failed to create issue field')
      }
    },
    [createMutation, navigate, orgId, orgLogin, reportUsage],
  )

  if (isLimitReached) {
    return null
  }

  return (
    <div>
      {apiError && (
        <Flash variant="danger" className="mb-3">
          {apiError}
        </Flash>
      )}
      <IssueFieldForm
        organizationLogin={payload.data.organization.login}
        pageTitle={Resources.newTitle}
        fieldNames={payload.data.fields.map(field => field.name)}
        confirmLabel={Resources.createButton}
        onSubmit={handleSubmit}
        isCreateNew
      />
    </div>
  )
}

try{ NewPage.displayName ||= 'NewPage' } catch {}