import {getFieldTypeOcticon, type IssueField, KnownTypes} from '@github-ui/issue-fields-shared/issue-field'
import {useIssueFieldsAnalytics} from '@github-ui/issue-fields-shared/use-issue-fields-analytics'
import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {Link} from '@github-ui/react-core/link'
import {useQueryClient} from '@github-ui/react-query'
import {VisuallyHidden} from '@primer/react'
import {Blankslate, DataTable} from '@primer/react/experimental'
import {useCallback, useRef, useState} from 'react'

import {Resources} from '../constants/strings'
import {useDeleteIssueFieldMutation} from '../mutations/delete-issue-field'
import {issueFieldsSettingsIndexRoute} from '../routes/index-route'
import type {Organization} from '../types/organization'
import {IssueFieldDeleteConfirmationDialog} from './IssueFieldDeleteConfirmationDialog'
import {IssueFieldItemMenu} from './IssueFieldItemMenu'
import styles from './IssueFieldsList.module.css'

type IssueFieldsListProps = {
  fields: IssueField[]
  organization: Organization
}

export function IssueFieldsList({fields, organization}: IssueFieldsListProps) {
  const queryClient = useQueryClient()
  const indexRouteQuery = useRouteQuery(issueFieldsSettingsIndexRoute, 'mainQuery')
  const {markInteractionStart, reportUsage} = useIssueFieldsAnalytics()

  const [isDeleteConfirmationDialogOpen, setIsDeleteConfirmationDialogOpen] = useState<boolean>(false)
  const [fieldPendingDeletion, setFieldPendingDeletion] = useState<IssueField | null>(null)
  const [deleteError, setDeleteError] = useState<string | null>(null)

  const deleteMutation = useDeleteIssueFieldMutation(organization.login)

  // Track the button that opened the dialog
  const lastAnchorButtonRef = useRef<HTMLButtonElement | null>(null)

  const onDeleteRequested = useCallback(
    (issueField: IssueField, anchorButton: HTMLButtonElement | null) => {
      if (issueField) {
        lastAnchorButtonRef.current = anchorButton
        setFieldPendingDeletion(issueField)
        setIsDeleteConfirmationDialogOpen(true)
        setDeleteError(null)
        markInteractionStart()
      }
    },
    [markInteractionStart],
  )

  const onDialogClose = () => {
    if (fieldPendingDeletion) {
      reportUsage({
        page: 'org#settings',
        action: 'delete',
        fieldId: fieldPendingDeletion.id,
        fieldType: fieldPendingDeletion.type,
        status: 'cancelled',
        singleSelectOptionsCount:
          fieldPendingDeletion.type === 'single_select' ? fieldPendingDeletion.options?.length : undefined,
        orgId: organization.id,
      })
    }

    setIsDeleteConfirmationDialogOpen(false)
    setFieldPendingDeletion(null)
    setDeleteError(null)
  }

  const onDeleteConfirmed = async () => {
    const startTime = Date.now()
    try {
      setDeleteError(null)
      if (fieldPendingDeletion) {
        await deleteMutation.mutateAsync(fieldPendingDeletion.id)
        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'delete',
          fieldId: fieldPendingDeletion.id,
          fieldType: fieldPendingDeletion.type,
          status: 'success',
          singleSelectOptionsCount:
            fieldPendingDeletion.type === 'single_select' ? fieldPendingDeletion.options?.length : undefined,
          duration,
          orgId: organization.id,
        })
        setIsDeleteConfirmationDialogOpen(false)
        setFieldPendingDeletion(null)
        queryClient.invalidateQueries({queryKey: indexRouteQuery.queryKey})
      }
    } catch (error) {
      const errorMessage = error instanceof Error ? error.message : 'Failed to delete issue field'
      if (fieldPendingDeletion) {
        const duration = Date.now() - startTime
        reportUsage({
          page: 'org#settings',
          action: 'delete',
          fieldId: fieldPendingDeletion.id,
          fieldType: fieldPendingDeletion.type,
          status: 'error',
          singleSelectOptionsCount:
            fieldPendingDeletion.type === 'single_select' ? fieldPendingDeletion.options?.length : undefined,
          duration,
          errorDetails: errorMessage,
          orgId: organization.id,
        })
      }
      setDeleteError(errorMessage)
    }
  }

  return (
    <div className={styles.list}>
      {fields.length === 0 ? (
        <Blankslate border>
          <Blankslate.Heading>{Resources.emptyStateHeading}</Blankslate.Heading>
          <Blankslate.Description>{Resources.emptyStateDescription}</Blankslate.Description>
        </Blankslate>
      ) : (
        <DataTable
          data={fields}
          columns={[
            {
              header: () => <div className={styles.header}>{Resources.issueFieldsListHeading(fields.length)}</div>,
              field: 'name',
              renderCell: field => {
                const FieldIcon = getFieldTypeOcticon(field.type)
                return (
                  <Link
                    className={styles.fieldName}
                    to={`/organizations/${organization.login}/settings/issue-fields/${field.id}`}
                  >
                    {FieldIcon && <FieldIcon size={16} className={styles.fieldIcon} />}
                    <strong>{field.name}</strong>
                  </Link>
                )
              },
            },
            {
              header: () => <VisuallyHidden>Type</VisuallyHidden>,
              field: 'type',
              renderCell: field => {
                const knownFieldType = KnownTypes[field.type]
                return <span className={styles.fieldCell}>{knownFieldType.displayName}</span>
              },
            },
            {
              header: () => <VisuallyHidden>Description</VisuallyHidden>,
              field: 'description',
              renderCell: field => {
                return <span className={styles.fieldCell}>{field.description}</span>
              },
            },
            {
              id: 'actions',
              header: () => <VisuallyHidden>Actions</VisuallyHidden>,
              renderCell: field => (
                <div className={styles.actions}>
                  <IssueFieldItemMenu
                    issueField={field}
                    onDelete={(issueField, anchorButton) => onDeleteRequested(issueField, anchorButton)}
                    organization={organization.login}
                  />
                </div>
              ),
            },
          ]}
        />
      )}
      <IssueFieldDeleteConfirmationDialog
        isOpen={isDeleteConfirmationDialogOpen}
        issueFieldName={fieldPendingDeletion?.name ?? null}
        onClose={onDialogClose}
        onConfirm={onDeleteConfirmed}
        returnFocusRef={lastAnchorButtonRef}
        error={deleteError}
      />
    </div>
  )
}

try{ IssueFieldsList.displayName ||= 'IssueFieldsList' } catch {}
try{ FieldIcon.displayName ||= 'FieldIcon' } catch {}