import {FormControl, Textarea} from '@primer/react'
import {forwardRef} from 'react'

import {ISSUE_FIELD_DESCRIPTION_LIMIT} from '../constants/constants'
import {Resources} from '../constants/strings'
import styles from '../routes/NewPage.module.css'

type IssueFieldDescriptionProps = {
  disabled?: boolean
  description: string
  error: string
  setDescription: (description: string) => void
  setError: (error: string) => void
}

export const IssueFieldDescription = forwardRef<HTMLTextAreaElement, IssueFieldDescriptionProps>(
  function IssueFieldDescription({error, setError, description, setDescription, disabled = false}, forwardedRef) {
    return (
      <FormControl disabled={disabled}>
        <FormControl.Label>{Resources.descriptionLabel}</FormControl.Label>
        <Textarea
          value={description}
          onChange={e => {
            setError('')
            setDescription(e.target.value)
          }}
          maxLength={ISSUE_FIELD_DESCRIPTION_LIMIT}
          placeholder={Resources.descriptionPlaceholder}
          name="description"
          validationStatus={error ? 'error' : undefined}
          ref={forwardedRef}
          className={styles.textArea}
          resize="none"
          rows={2}
          block
        />
        {error && <FormControl.Validation variant="error">{error}</FormControl.Validation>}
      </FormControl>
    )
  },
)

try{ IssueFieldDescription.displayName ||= 'IssueFieldDescription' } catch {}
try{ IssueFieldDescription.displayName ||= 'IssueFieldDescription' } catch {}