import {SingleSelectForm} from '@github-ui/shared-single-select-components/SingleSelectForm'
import type {NewSingleSelectOption, SingleSelectOptionWithId} from '@github-ui/shared-single-select-components/types'
import {useIncrementer} from '@github-ui/shared-single-select-components/useIncrementer'
import {buildNewSingleSelectOption} from '@github-ui/shared-single-select-components/util'
import {useEffect, useState} from 'react'

import styles from '../routes/NewPage.module.css'

type IssueFieldOptionsProps = {
  disabled?: boolean
  options?: SingleSelectOptionWithId[]
  onOptionsChange?: (options: SingleSelectOptionWithId[]) => void
}

export function IssueFieldOptions({
  disabled = false,
  options: externalOptions,
  onOptionsChange,
}: IssueFieldOptionsProps) {
  const [options, setOptions] = useState<SingleSelectOptionWithId[]>(externalOptions || [])
  const getNextID = useIncrementer({start: 1})

  // Notify parent of changes
  useEffect(() => {
    // notify the parent only if options actually changed
    if (externalOptions !== options) onOptionsChange?.(options)

    // excluding externalOptions as it is covered by the next useEffect
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [options, onOptionsChange])

  // sync with external options changes (like previous save actions)
  useEffect(() => {
    if (externalOptions) {
      setOptions(externalOptions)
    }
  }, [externalOptions])

  const handleAddOption = (option: NewSingleSelectOption) => {
    if (disabled) return
    const newOption = buildNewSingleSelectOption(getNextID(), option, options)
    setOptions(prevOptions => [...prevOptions, newOption])
  }

  const handleUpdateOption = (updatedOption: SingleSelectOptionWithId) => {
    if (disabled) return
    setOptions(prevOptions => prevOptions.map(option => (option.id === updatedOption.id ? updatedOption : option)))
  }

  const handleRemoveOption = (id: string) => {
    if (disabled) return
    setOptions(prevOptions => prevOptions.filter(option => option.id !== id))
  }

  const handleDrop = ({
    dragMetadata,
    dropMetadata,
    isBefore,
  }: {
    dragMetadata: {id: string}
    dropMetadata: {id: string}
    isBefore: boolean
  }) => {
    if (disabled || dragMetadata.id === dropMetadata.id) return

    const dragIndex = options.findIndex(opt => opt.id === dragMetadata.id)
    const dropIndex = options.findIndex(opt => opt.id === dropMetadata.id)

    if (dragIndex === -1 || dropIndex === -1) return

    const newOptions = [...options]
    const [draggedItem] = newOptions.splice(dragIndex, 1)

    if (draggedItem) {
      // Adjust the drop index if the dragged item was before the drop target
      const adjustedDropIndex = dragIndex < dropIndex ? dropIndex - 1 : dropIndex
      const insertIndex = isBefore ? adjustedDropIndex : adjustedDropIndex + 1
      newOptions.splice(insertIndex, 0, draggedItem)
    }

    setOptions(newOptions)
  }

  return (
    <div className={styles.singleSelectFormContainer}>
      <SingleSelectForm
        options={options}
        canRemoveOption
        maxNumberOfOptions={100} // MAX_OPTIONS_PER_FIELD
        onAddOption={handleAddOption}
        onUpdateOption={handleUpdateOption}
        onRemoveOption={handleRemoveOption}
        onDrop={handleDrop}
        noDuplicatedOptions
        enableNameLengthValidation
      />
    </div>
  )
}

try{ IssueFieldOptions.displayName ||= 'IssueFieldOptions' } catch {}