import {useNavigate} from '@github-ui/use-navigate'
import {Button} from '@primer/react'
import {useCallback, useRef, useState} from 'react'

import {useDeleteIssueFieldMutation} from '../mutations/delete-issue-field'
import {IssueFieldDeleteConfirmationDialog} from './IssueFieldDeleteConfirmationDialog'

type IssueFieldsDeleteProps = {
  issueFieldName: string
  issueFieldId: string
  organization: string
}

export const IssueFieldsDelete = ({issueFieldName: name, issueFieldId: id, organization}: IssueFieldsDeleteProps) => {
  const [isDeleteConfirmationDialogOpen, setIsDeleteConfirmationDialogOpen] = useState<boolean>(false)
  const [issueFieldPendingDeletion, setIssueFieldPendingDeletion] = useState<string | null>(null)
  const deleteBtnRef = useRef<HTMLButtonElement | null>(null)

  const onDeleteRequested = useCallback(() => {
    setIssueFieldPendingDeletion(name)
    setIsDeleteConfirmationDialogOpen(true)
  }, [name])

  const onDialogClose = () => {
    setIsDeleteConfirmationDialogOpen(false)
    setIssueFieldPendingDeletion(null)
    setDeleteError(null)
  }
  const navigate = useNavigate()
  const deleteMutation = useDeleteIssueFieldMutation(organization)
  const [deleteError, setDeleteError] = useState<string | null>(null)
  // Delete issue field on edit page
  // Make the call to delete when user confirms the deletion
  const onDeleteConfirmed = async () => {
    try {
      setDeleteError(null)
      await deleteMutation.mutateAsync(id)
      onDialogClose()
      navigate(`/organizations/${organization}/settings/issue-fields`, {reloadDocument: true})
    } catch (error) {
      setDeleteError(error instanceof Error ? error.message : 'Failed to delete issue field')
    }
  }
  return (
    <>
      <Button variant="danger" data-testid="danger-zone-delete-btn" onClick={onDeleteRequested}>
        Delete
      </Button>

      <IssueFieldDeleteConfirmationDialog
        isOpen={isDeleteConfirmationDialogOpen}
        issueFieldName={issueFieldPendingDeletion}
        onClose={onDialogClose}
        onConfirm={onDeleteConfirmed}
        error={deleteError}
        // This is to keep the types strong. We redirect user to index page eventually.
        returnFocusRef={deleteBtnRef}
      />
    </>
  )
}

try{ IssueFieldsDelete.displayName ||= 'IssueFieldsDelete' } catch {}