import {FormControl, TextInput} from '@primer/react'
import {forwardRef, useCallback} from 'react'

import {ISSUE_FIELD_NAME_LIMIT, RESERVED_NAMES, VALID_NAME_REGEX} from '../constants/constants'
import {Resources} from '../constants/strings'
import styles from '../routes/NewPage.module.css'

type IssueFieldNameProps = {
  disabled?: boolean
  name: string
  error: string
  setName: (name: string) => void
  setError: (error: string) => void
}

export const IssueFieldName = forwardRef<HTMLInputElement, IssueFieldNameProps>(function IssueFieldName(
  {error, setError, name, setName, disabled = false},
  forwardedRef,
) {
  const onChange = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      setError('')
      const value = e.target.value
      setName(value)
      const isEmpty = value.trim() === ''
      if (isEmpty) return
      // If the field is empty, we don't want to show any further validation errors.
      // If user tries to submit an empty field, the error will be shown at that time.
      const isInvalidInput = !VALID_NAME_REGEX.test(value)
      if (isInvalidInput) {
        setError(Resources.nameInvalidCharactersError)
        return
      }
      const isReservedName = RESERVED_NAMES.includes(value.trim().toLowerCase())
      if (isReservedName) {
        setError(Resources.nameReservedError(value))
        return
      }
      const nameTooLong = value.length > ISSUE_FIELD_NAME_LIMIT
      if (nameTooLong) {
        setError(Resources.nameTooLongErrorMessage(ISSUE_FIELD_NAME_LIMIT))
        return
      }
    },
    [setError, setName],
  )

  return (
    <FormControl disabled={disabled} required>
      <FormControl.Label>{Resources.nameLabel}</FormControl.Label>
      <TextInput
        value={name}
        onChange={onChange}
        placeholder={Resources.namePlaceholder}
        name="name"
        validationStatus={error ? 'error' : undefined}
        ref={forwardedRef}
        className={styles.textInput}
      />
      {error && <FormControl.Validation variant="error">{error}</FormControl.Validation>}
    </FormControl>
  )
})

try{ IssueFieldName.displayName ||= 'IssueFieldName' } catch {}